/**
 * The structural model for the ONE HCL parse/render surface (plan §4.1).
 * Extractors consume TfBlock; toHcl emitters produce TfBlock. A second HCL
 * dialect cannot exist because a second parser/renderer doesn't.
 *
 * Expressions are tagged with `$expr` (not the plan sketch's bare `kind`)
 * so a plain object value from a jsonencode payload can never be mistaken
 * for an expression — payload objects are user data and may contain any key,
 * so parseJsonencodePayload loud-errors on a literal `$expr` key instead.
 */
/** One step in an attribute path: a field name, or a map-key index like ["Name"]. */
export type PathSeg = string | {
    index: string;
};
export type TfExpr = 
/** elementum_app.x.id · elementum_app.x.refs["Name"] */
{
    $expr: "resource-attr";
    type: string;
    label: string;
    path: PathSeg[];
}
/** data.elementum_category.x.id */
 | {
    $expr: "data-attr";
    type: string;
    label: string;
    path: PathSeg[];
}
/** local.itsm_title_field_id · local.stage_ids_by_key["approve"] */
 | {
    $expr: "local";
    name: string;
    path: PathSeg[];
}
/** var.secret_name — used for sensitive organization credentials. */
 | {
    $expr: "variable";
    name: string;
    path: PathSeg[];
}
/** jsonencode({ ... }) — value is the payload as plain data */
 | {
    $expr: "jsonencode";
    value: TfValue;
}
/** "text${expr}text" — parts alternate literal text and expressions */
 | {
    $expr: "template";
    parts: (string | TfExpr)[];
}
/** a for-loop variable reference inside a for-object: s.name */
 | {
    $expr: "scoped-attr";
    name: string;
    path: PathSeg[];
}
/** { for s in <collection> : s.name => s.id } — ei's label→id lookup maps */
 | {
    $expr: "for-object";
    variable: string;
    collection: TfExpr;
    key: TfExpr;
    value: TfExpr;
};
export type TfValue = string | number | boolean | null | TfValue[] | {
    [k: string]: TfValue;
} | TfExpr;
export type TfBlockKind = "resource" | "data" | "locals" | "import" | "provider" | "terraform" | "variable";
export interface TfBlock {
    kind: TfBlockKind;
    /** resource/data only: the terraform type, e.g. "elementum_app" */
    type?: string;
    /** resource/data: the label; provider: the provider name */
    label?: string;
    attrs: Record<string, TfValue>;
}
export interface TfDocument {
    blocks: TfBlock[];
}
export declare function isTfExpr(v: TfValue): v is TfExpr;
export declare const expr: {
    resourceAttr(type: string, label: string, path?: PathSeg[]): TfExpr;
    dataAttr(type: string, label: string, path?: PathSeg[]): TfExpr;
    local(name: string, path?: PathSeg[]): TfExpr;
    variable(name: string, path?: PathSeg[]): TfExpr;
    jsonencode(value: TfValue): TfExpr;
    template(parts: (string | TfExpr)[]): TfExpr;
    scopedAttr(name: string, path?: PathSeg[]): TfExpr;
    forObject(variable: string, collection: TfExpr, key: TfExpr, value: TfExpr): TfExpr;
};
